<?php namespace Workspace; $pid=(int)$project['id'];$r=$deliveryRelease;$rid=(int)$r['id']; ?>
<p><a href="<?= h(url('project',['id'=>$pid])) ?>">← <?= h($project['title']) ?></a> · <a href="<?= h(url('releases',['project'=>$pid,'id'=>$rid])) ?>">Выпуск</a> · <a href="<?= h(url('deployments',['project'=>$pid])) ?>">Развёртывания</a></p>
<p><a href="<?= h(url('release_trace',['project'=>$pid,'id'=>$rid])) ?>">След выпуска и эксплуатации (MFA)</a></p><section class="panel"><h2>Поставка <?= h($r['tag']) ?> · <?= h($r['state']) ?></h2>
<p>SHA: <code><?= h($r['commit_sha']) ?></code></p><p>Артефакт <?= h($r['artifact_name']) ?> · SHA-256 <code><?= h($r['artifact_sha256']) ?></code></p>
<?php if(!$deliveryActive): ?><p class="planning-warning">Подключение GitHub изменено или отключено. Подтверждение QA недоступно.</p><?php endif ?>
<?php if(!$deliveryScopes): ?><p>Исторический выпуск: критерии и дополнительные PR не были зафиксированы. Для QA создайте новую карточку выпуска.</p><?php endif ?>
<?php if($deliveryEvidence): ?><p>Снимок CI для точного SHA от <?= h(gmdate('Y-m-d H:i:s',(int)$r['verified_at'])) ?> UTC; не текущая проверка GitHub.</p><ul><?php foreach($deliveryEvidence['ci']['checks']??[] as $c): ?><li><?= h($c['name']) ?> · #<?= (int)$c['id'] ?> · <?= h($c['conclusion']) ?></li><?php endforeach ?></ul><?php endif ?>
<?php foreach($deliveryScopes as $s): ?><article class="panel inset"><h3><a href="<?= h(url('task',['id'=>$s['task_id']])) ?>">#<?= (int)$s['task_id'] ?> <?= h($s['title']) ?></a></h3><p>Версия задачи <?= (int)$s['task_version'] ?> · <?= $s['current']?'актуальна':'историческая' ?> · <?= $s['verified']?'PR подтверждены в SHA':'PR не подтверждены' ?></p><h4>Критерии приёмки</h4><pre class="release-text"><?= h($s['criteria']) ?></pre><p>Основной PR #<?= (int)$s['pr_number'] ?><?php foreach(json_decode($s['extra_prs'],true,16,JSON_THROW_ON_ERROR) as $n): ?> · PR #<?= (int)$n ?><?php endforeach ?></p>
<?php if($s['verified']): ?><ul><?php foreach($deliveryEvidence['tasks'] as $t): if((int)$t['task_id']!==(int)$s['task_id'])continue; ?><li><a rel="noreferrer" href="<?= h('https://github.com/'.ghName($deliveryRepository['full_name']).'/pull/'.(int)$t['pr']['number']) ?>">PR #<?= (int)$t['pr']['number'] ?></a> · head <code><?= h($t['pr']['head_sha']) ?></code> · merge <code><?= h($t['pr']['merge_sha']) ?></code></li><?php endforeach ?></ul><?php endif ?></article><?php endforeach ?></section>
<section class="panel"><h2>Окружения и QA</h2><p>Последнее управляемое развёртывание сайта, а не live-проверка хоста. Любая более новая попытка, неопределённый результат или изменённая привязка блокируют приёмку прежнего наблюдения.</p>
<?php foreach($deliverySites as $site): $d=$site['deployment']; ?><article class="panel inset"><h3><?= h($site['kind']) ?> · <?= h($site['environment_name']) ?> · <?= h($site['site_name']) ?></h3>
<?php if(!$d): ?><p>Нет наблюдений развёртывания.</p><?php else: ?><p>Последнее задание #<?= (int)$d['id'] ?> · <?= h($d['state']) ?> · <?= h($d['observed_tag']) ?> · целевой SHA <code><?= h($d['observed_sha']) ?></code><?php if($d['finished_at']!==null): ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$d['finished_at'])) ?> UTC<?php endif ?></p><?php endif ?>
<?php if($site['observed']): ?><p>Последний подтверждённый фактический SHA: <code><?= h($site['observed']['sha']) ?></code> · SHA-256 <code><?= h($site['observed']['digest']) ?></code></p><?php endif ?><p><?= $site['matches']?'Точный SHA и артефакт подтверждены исполнителем при последнем развёртывании.':'Нет подтверждённого наблюдения этой поставки в данном окружении.' ?></p>
<?php foreach($deliveryScopes as $s): $review=$site['reviews'][(int)$s['task_id']]??null; $eligible=$site['matches']&&$s['current']&&$s['verified']&&trim($s['criteria'])!==''; ?>
<h4>QA задачи #<?= (int)$s['task_id'] ?></h4><?php if($review): ?><p><?= $eligible?'Последнее решение':'Историческое решение' ?>: <?= h($review['outcome']) ?> · #<?= (int)$review['actor_id'] ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$review['created_at'])) ?> UTC</p><pre class="release-text"><?= h($review['notes']) ?></pre><?php else: ?><p>Не принято QA.</p><?php endif ?>
<?php if($eligible): ?><form method="post"><?php formFields('release.qa') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="id" value="<?= $rid ?>"><input type="hidden" name="task_id" value="<?= (int)$s['task_id'] ?>"><input type="hidden" name="deployment_id" value="<?= (int)$d['id'] ?>"><input type="hidden" name="fingerprint" value="<?= h(deliveryFingerprint($r,$s,$d,$review)) ?>"><label>Результат проверки критериев<select name="outcome" required><option value="">Выберите</option><option value="passed">Принято</option><option value="failed">Не принято</option></select></label><label>Доказательства / результаты испытаний<textarea name="notes" required maxlength="2000" rows="3"></textarea></label><button class="primary">Зафиксировать QA (MFA)</button></form><?php endif ?><?php endforeach ?></article><?php endforeach ?>
<?php if(!$deliverySites): ?><p>Нет зарегистрированных сайтов проекта.</p><?php endif ?></section>

<?php if($deliveryHistory): ?><section class="panel"><h2>История QA (последние 100 решений)</h2><p>Исторические решения не переносятся на новый SHA или новый деплой.</p><?php foreach($deliveryHistory as $q): ?><p>Задача #<?= (int)$q['task_id'] ?> · сайт #<?= (int)$q['site_id'] ?> · деплой #<?= (int)$q['deployment_id'] ?> · <?= h($q['outcome']) ?> · сотрудник #<?= (int)$q['actor_id'] ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$q['created_at'])) ?> UTC</p><pre class="release-text"><?= h($q['notes']) ?></pre><?php endforeach ?></section><?php endif ?>
